//! The object registry: every NID OpenSSL assigns, with its names and OID. The tables are
//! generated by `cargo xtask codegen` from the vendored headers.

/// One entry of the object table.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct ObjectDef {
    /// OpenSSL's numeric identifier for the object (NID).
    pub nid: i32,
    /// Short name (`SN_`). OpenSSL fills it from the long name when an object has none.
    pub short_name: &'static str,
    /// Long name (`LN_`), likewise filled from the short name.
    pub long_name: &'static str,
    /// Content octets of the DER-encoded OBJECT IDENTIFIER; empty for objects without one,
    /// including the single-arc roots `undef`, `iso`, `itu-t`, and `joint-iso-itu-t`.
    pub der: &'static [u8],
}

/// A signature algorithm with the digest and public-key algorithm it combines, as NIDs.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct SignatureAlgorithm {
    pub signature: i32,
    pub digest: i32,
    pub pkey: i32,
}

/// Every object, indexed by NID. `None` marks NIDs that aren't assigned.
pub fn objects() -> &'static [Option<ObjectDef>] {
    crate::generated::objects::OBJECTS
}

/// The signature algorithms OpenSSL can map to a digest and a public-key algorithm.
pub fn signature_algorithms() -> &'static [SignatureAlgorithm] {
    crate::generated::objects::SIGNATURE_ALGORITHMS
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn table_is_indexed_by_nid() {
        for (index, object) in objects().iter().enumerate() {
            if let Some(object) = object {
                assert_eq!(usize::try_from(object.nid).unwrap(), index);
            }
        }
    }

    #[test]
    fn well_known_objects() {
        let sha256 = objects()
            .iter()
            .flatten()
            .find(|o| o.short_name == "SHA256");
        let sha256 = sha256.expect("SHA256 is in the table");
        assert_eq!(sha256.long_name, "sha256");
        assert_eq!(
            sha256.der,
            [0x60, 0x86, 0x48, 0x01, 0x65, 0x03, 0x04, 0x02, 0x01]
        );
        let undef = objects()[0].expect("NID 0 is undef");
        assert_eq!((undef.short_name, undef.long_name), ("UNDEF", "undefined"));
        assert!(undef.der.is_empty());
    }

    #[test]
    fn signature_algorithms_refer_to_known_objects() {
        // Holes in the table are `None`, so an assigned NID is `Some(Some(_))`.
        let known = |nid: i32| {
            usize::try_from(nid)
                .ok()
                .and_then(|i| objects().get(i))
                .is_some_and(Option::is_some)
        };
        assert!(!signature_algorithms().is_empty());
        for row in signature_algorithms() {
            assert!(
                known(row.signature) && known(row.digest) && known(row.pkey),
                "{row:?}"
            );
        }
    }
}
